const t={ui:{fig:"Abb. 3",title:"Ecken abnähen",svgLabel:"Eine isometrische Zeichnung, wie man Ecken abnäht: die Tasche an den Seiten und am Boden genäht, jede untere Ecke zu einem Dreieck aufgefaltet, die Seitennaht auf der Bodennaht, quer darüber im Abstand der halben Bodenbreite vom Nahtende eine Linie angezeichnet und genäht, die Spitze mit etwas Nahtzugabe abgeschnitten, die Tasche gewendet – mit flachem Boden.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Hinstellen",putTogether:"Boden zeigen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT"},stitches:{straight:"Geradstich"},labels:{rightSides:"rechts auf rechts",sidesBottom:"Seiten und Boden",aPouch:"ein flacher Beutel",standUp:"kopfüber hinstellen",openCorner:"Ecke auffalten",seamOnSeam:"Naht auf Naht",triangle:"ein Dreieck",seamEnd:"Nahtende",halfBase:"halbe Bodenbreite",baseWidth:"Bodenbreite",sewLine:"auf der Linie nähen",backstitch:"verriegeln",bothCorners:"beide Ecken",trimTip:"Spitze abschneiden",smallAllowance:"etwas Nahtzugabe",turnOut:"auf rechts wenden",flatBottom:"ein flacher Boden",cornerSeam:"Ecknaht"},steps:[{title:"Ecken abnähen",text:"Der Taschenboden, die Tasche steht kopf: ein flacher Boden mit der Bodennaht in der Mitte und einer kurzen Quernaht an jedem Ende, dort, wo die Seitennaht auf sie trifft. Tippe auf die Tasche, um sie hinzustellen."},{title:"Tasche nähen",text:"Leg das Vorderteil rechts auf rechts auf das Rückenteil und nähe die Seiten und den Boden: ein flacher Beutel, aus den Ecken ist nichts ausgeschnitten.",details:["Leg das Vorderteil rechts auf rechts auf das Rückenteil und fixiere die Teile mit Klammern.","Nähe beide Seiten und den Boden.","Aus den Ecken wird nichts ausgeschnitten: Der Boden entsteht in den nächsten Schritten.","Ist die Tasche ein einziges Stück, am Boden gefaltet, gibt es keine Bodennaht: Dann kommt die Seitennaht auf den Bodenbruch."]},{title:"Ecke auffalten",text:"Zieh Vorder- und Rückenteil an einer unteren Ecke auseinander und leg die Ecke flach, sodass die Seitennaht genau auf der Bodennaht liegt: Die Ecke wird zu einem Dreieck.",details:["Zieh Vorder- und Rückenteil an einer unteren Ecke auseinander.","Leg die Ecke flach, sodass die Seitennaht genau auf der Bodennaht liegt (oder auf dem Bodenbruch).","Die Ecke ist jetzt ein Dreieck; die Naht läuft in seiner Mitte bis zum Nahtende an der Spitze.","Falte die andere untere Ecke genauso auf.","In der Zeichnung steht die Tasche kopfüber auf ihrer offenen Oberkante, damit beide Ecken zu sehen sind."]},{title:"Linie anzeichnen",text:"Zeichne quer über das Dreieck eine Linie, im rechten Winkel zur Naht, im Abstand der halben Bodenbreite vom Nahtende. Dann ist die Linie so lang, wie der Boden breit ist.",details:["Überleg dir, wie breit der Boden werden soll: Das ist die Bodenbreite.","Miss die halbe Bodenbreite entlang der Naht ab, vom Nahtende aus, wo sich die Nähte an der Spitze treffen – nicht von der Stoffspitze.","Zeichne dort quer über das Dreieck eine Linie, im rechten Winkel zur Naht. Sie ist so lang, wie der Boden breit ist.","Je weiter die Linie von der Spitze entfernt ist, desto breiter wird der Boden. Zeichne die andere Ecke genauso an."]},{title:"Auf der Linie nähen",text:"Nähe auf der angezeichneten Linie und verriegle am Anfang und am Ende.",details:["Nähe auf der Linie von einer Kante des Dreiecks zur anderen.","Verriegle am Anfang und am Ende, damit die Naht hält.","Näh die andere Ecke genauso."]},{title:"Spitze abschneiden",text:"Schneide die Spitze jedes Dreiecks ab und lass hinter der Naht etwas Nahtzugabe stehen.",details:["Schneide die Spitze entlang der Naht ab und lass etwas Nahtzugabe stehen.","Schneide nicht in die Naht.","Arbeite alle unteren Ecken so – und auch die Ecken des Futters, wenn die Tasche ein Futter hat."]},{title:"Wenden",text:"Wende die Tasche auf rechts: Sie hat einen flachen Boden, mit einer kurzen Ecknaht quer an jedem Ende.",details:["Wende die Tasche auf rechts und drück die Ecken heraus.","Der Boden ist flach und so breit, wie die Linie lang war. An jedem Ende trifft die Seitennaht auf die Mitte der Ecknaht."]}],legend:[{title:"Boden",text:"flach · so breit, wie die Ecknähte lang sind"},{title:"Bodennaht",text:"verbindet Vorder- und Rückenteil · in der Mitte des Bodens"},{title:"Ecknähte",text:"quer über die Ecke genäht, im Abstand der halben Bodenbreite vom Nahtende"},{title:"Seitennähte",text:"jede trifft auf die Mitte einer Ecknaht"}]};export{t as default};
